---@param roleCardVo CardVo
function CommonBossDetailsDialog:FillBossInfo(roleCardVo)
    if not roleCardVo then
        return
    end
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(roleCardVo.skinId)
    CfUtils.FillText(self.BossName, skinVo.name)
    
    for i = 1, 6 do
        local num = (i == 1 and "" or i)
        local skillId = roleCardVo["atkSkill"..num]
        if checkNumber(skillId) > 0 then
            ---@type SkillCardVo
            local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillId)
            if skillCardVo then
                local go = CfUtils.InstantiateGo(self.SkillGroup, self.BossSkills)
                local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIWorldBoss.UIWorldBossDetailsDialog.UIWorldBossSkillNode")
                if scr then
                    scr:Refresh(skillCardVo)
                end
            end
        end
    end
end

function CommonBossDetailsDialog:RefreshSummonMonsterByIndex(listView, index)
    local luaIndex = index + 1
    ---@type MonsterTypeVo
    local cellData = self._followMonsters[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type CommonMonstCardNode
    local scr = CfUtils.GetLuaScr(cell.gameObject.transform:Find("CommonMonstCardNode"), "Game.Behaviours.CommonMonstCardNode")
    scr:RefeshMonstHeadIcon(cellData, cell.gameObject)
    return cell
end

function CommonBossDetailsDialog:FillMonsterInfo()
    if isNull(self.lineUpInfo) then
        return
    end
    
    for _, line in ipairs(self.lineUpInfo) do
        local attributes = line.attribute
        local ids = type(line.wave1NpcId) == "table" and line.wave1NpcId or {line.wave1NpcId}
        for index, id in ipairs(ids) do
            local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(id)
            if vo then
                local attribute = attributes[index]
                if attribute then
                    vo.attribute = attribute
                end
                print("vo =>" , vo.monsterClass)
                if checkNumber(vo.monsterClass) == Constants.RoleClass.Boss or checkNumber(vo.monsterClass) == Constants.RoleClass.Elite then
                    local modeId = vo.mode
                    --[[ ---@type CardVo
                     --local roleVo = CfUtils.GetCfVo(AutoIds.IdSetting28, "CardVo", checkNumber(modeId))]]
                    --local roleVo = CardConfMgr:GetInstance():GetMonsterTypeVoById(checkNumber(modeId))
                    self:FillBossInfo(vo)
                else
                    table.insert(self._followMonsters, vo)
                end
            end
        end
    end
    print("self._followMonsters =>" , table.dump(self._followMonsters))
    self.LoopView:InitGridView(#self._followMonsters, Bind(self, self.RefreshSummonMonsterByIndex))
end
--endregion get / set

